const normalize=s=>s.replace(/[\s。？！?！!，,、.]/g,'').trim();function answer(ok,b){const s=session;if(s.answered)return;if((s.mode==='pronunciation'||s.mode==='spokenResponse')&&ok&&!s.speechVerified)return;if(s.mode==='typedResponse'&&ok&&!s.typedVerified)return;if(s.mode==='writing'&&(!requiresWriting(s.queue[s.index])||(ok&&!s.writingVerified)))return;s.answered=true;recordQuestAnswer(ok&&!s.hinted);showAvatarReaction(ok);const w=s.queue[s.index];state.wordSkills=state.wordSkills||{};const skillMode=s.mode==='typedResponse'?'characters':s.mode==='spokenResponse'?'pronunciation':s.mode;const skills=isVocabularyWord(w)?(state.wordSkills[w.id]=state.wordSkills[w.id]||{}):{};if(ok&&!s.hinted){s.correct++;if(isVocabularyWord(w)){skills[skillMode]=s.mode==='writing'?writingChars(w).every(c=>state.wordWriting?.[w.id]?.includes(c)):true;state.mastery[w.id]=skillCount(w);}state.daily=state.daily?.date===today()?state.daily:{date:today(),n:0};state.daily.n+=10;reward(10)}else{if(isVocabularyWord(w)){if(!ok)skills[skillMode]=false;state.mastery[w.id]=skillCount(w)}save()}document.querySelectorAll('[data-answer]').forEach(x=>{x.disabled=true;const good=s.options[+x.dataset.answer].correct;if(good&&(!s.isFinal||x===b))x.classList.add('correct');else if(x===b)x.classList.add('wrong')});const checklist=$('.skill-checklist');if(checklist)checklist.innerHTML=skillChecklist(w).replace(/^<div class="skill-checklist">|<\/div>$/g,'');$('.feedback').textContent=(ok?(s.hinted?'Practice done. Try without hints next time; this skill is still pending. ':(s.mode==='writing'?'Writing verified! +10 XP · +':'Skill checked! +10 XP · +')+s.lastPoints+' quest score'+(s.combo>=3?' · '+s.combo+'-answer combo!':'')+'. '):'Keep practicing; this skill is still pending. ')+w.zh+' · '+w.py+' — '+w.en;if(!isVocabularyWord(w))$('.feedback').textContent=(ok?'Phrase practice complete. ':'Keep practicing. ')+w.zh+' · '+w.py+' — '+w.en+' · No mastery requirement.';if(s.isFinal)$('.feedback').textContent=ok?'Check passed.':'This check did not pass. Review it after the final test.';$('#next').disabled=false;$('#next').textContent='Continue →'}
function startStudyBreak(){const s=session;if(!s||!settleQuest(s).finished)return false;if(!s.breakGame){const treats=[{pair:'berry',icon:'🍓',name:'strawberry'},{pair:'cookie',icon:'🍪',name:'cookie'},{pair:'tea',icon:'🧋',name:'bubble tea'}];const cards=treats.flatMap(t=>[{...t},{...t}]);for(let i=cards.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[cards[i],cards[j]]=[cards[j],cards[i]]}s.breakGame={cards,flipped:[],matched:[],moves:0,message:'Tap two cards to find a matching snack pair.'}}renderStudyBreak();return true}
function chooseBreakCard(index){const s=session,g=s?.breakGame;if(!g||!Number.isInteger(index)||!g.cards[index]||g.matched.length===3||g.matched.includes(g.cards[index].pair))return false;if(g.flipped.length===2)g.flipped=[];if(g.flipped.includes(index))return false;g.flipped.push(index);if(g.flipped.length===2){g.moves++;const first=g.cards[g.flipped[0]],second=g.cards[g.flipped[1]];if(first.pair===second.pair){g.matched.push(first.pair);g.message='A sweet match! Find the next pair.';g.flipped=[]}else g.message='Not a match yet. Tap another card to try again.'}else g.message='One card turned over. Choose another!';if(g.matched.length===3){if(!s.breakRewardClaimed&&settleQuest(s).finished){s.breakRewardClaimed=true;state.points+=3;save();updateHeader()}g.message='All three pairs found! Your study-break reward is 3 avatar points.'}renderStudyBreak();return true}
function renderStudyBreak(){const s=session,g=s.breakGame,done=g.matched.length===3;$('#lesson-content').innerHTML=`<div class="modal-top"><span class="eyebrow">A LITTLE STUDY BREAK</span><button class="close" aria-label="Return to lesson results">×</button></div><div class="break-buddy">${avatarSVG()}<div><h2>Snack match with ${esc(avatarName())}</h2><p>Take a breath. Match 3 pairs for 3 avatar points.</p></div></div><div class="break-progress"><b>${g.matched.length}/3 pairs found</b><span>${g.moves} turns</span></div><div class="break-board" aria-label="Snack matching game">${g.cards.map((card,i)=>{const matched=g.matched.includes(card.pair),visible=matched||g.flipped.includes(i);return `<button class="break-card ${matched?'matched':visible?'flipped':''}" data-break-card="${i}" ${matched||done?'disabled':''} aria-label="Card ${i+1}: ${visible?card.name+(matched?', matched':''):'face down'}" aria-pressed="${visible}">${visible?`<span aria-hidden="true">${card.icon}</span>`:'<span aria-hidden="true">✦</span>'}</button>`}).join('')}</div><p id="break-message" class="break-message" role="status">${g.message}</p>${done?'<div class="quest-treasure">🎁 +3 avatar points · Break complete!</div>':''}<div id="break-reaction" class="answer-reaction" hidden></div><div class="break-actions"><button class="primary" id="break-return">${done?'Back to my lesson →':'Skip break & return'}</button></div>`;document.querySelectorAll('[data-break-card]').forEach(b=>b.onclick=()=>chooseBreakCard(+b.dataset.breakCard));$('.close').onclick=()=>finish();$('#break-return').onclick=()=>finish();if(done)showAvatarReaction(true,'#break-reaction')}
function finish(){if(session.isFinal){finishFinalExam();return}let s=session,quest=settleQuest(s),l=levels[s.i],ready=practiceReady(l);if(s.phrasesOnly&&quest.finished&&!s.phrasePracticeSettled){state.phraseGroupCursor=state.phraseGroupCursor||{};state.phraseGroupCursor[s.i]=(s.focusGroup+1)%s.focusGroupCount;s.phrasePracticeSettled=true;save()}let earned=0;if(!s.review&&isLevelComplete(s.i)&&s.correct===s.queue.length&&!s.rewarded){earned=25;state.points+=25;s.rewarded=true;save()}$('#lesson-content').innerHTML=`<div class="prompt"><span class="eyebrow">${s.review?"PRACTICE QUEST":"QUEST RESULTS"}</span><div class="quest-finish-stars">${questStars(quest.stars)}</div><div class="quest-finish-avatar">${avatarSVG()}</div><h1>${s.phrasesOnly?'A little conversation practice!':isLevelComplete(s.i)?'Level mastered!':ready?'Ready for your final test!':quest.stars===3?'Perfect quest!':quest.stars>0?'A little adventure, a big win!':'Every adventure helps you grow.'}</h1><p>${s.correct} of ${s.queue.length} answered independently.</p><p class="quest-help">Focus group ${s.focusGroup+1}/${s.focusGroupCount}: ${s.focusWords.map(w=>esc(w.zh)).join(' · ')}. ${s.phrasesOnly?'This is optional practice, with no mastery requirement.':s.choiceWords.every(isWordMastered)?'Group mastered! Your next quiz can move forward.':'Your next quiz stays with the unfinished words in this group.'}</p><div class="quest-summary"><span><b>${s.score||0}</b>Quest score</span><span><b>${s.bestCombo||0}</b>Best combo</span></div>${quest.bonus?`<div class="quest-treasure">🎁 New star treasure! +${quest.bonus} avatar points</div>`:""}<p class="quest-help">Stars track this quest. Words require all five skills. Phrases are lesson practice only and have no mastery requirement.</p>${earned?`<div class="points-earned">◉ +${earned} avatar points!</div><p>Spend your points on a new look for your learning journey.</p><button class="secondary" id="customize">Build my avatar →</button>`:''}<p>${s.phrasesOnly?'Keep using these phrases in conversation. This practice has no mastery requirement.':isLevelComplete(s.i)?'You’ve completed this level. Choose any level to keep learning.':ready?'All practice checks are complete. Pass the full final test to finish this level.':`Complete the vocabulary word checks, then pass the word-only final test. Phrases are optional practice. ${vocabularyWords(l).filter(isWordMastered).length} / ${vocabularyWords(l).length} words mastered.`}</p>${levelProgressMarkup(l,s.i,true)}${finalExamCard(l,s.i)}${quest.finished?`<section class="study-break-offer"><h3>Time for a tiny study break?</h3><p>Match three snack pairs with ${esc(avatarName())} and earn 3 avatar points.</p><button class="secondary" id="break-play" ${s.breakRewardClaimed?'disabled':''}>${s.breakRewardClaimed?'✓ Break reward collected':'Play snack match · +3 points'}</button></section>`:''}<button class="primary" id="again">Play another quest →</button> <button class="secondary" id="done">Back to path</button></div>`;if($('#customize'))$('#customize').onclick=()=>{$('#lesson').close();tab='avatar';render()};if($('#break-play'))$('#break-play').onclick=()=>startStudyBreak();$('#again').onclick=()=>start(s.i,s.review,s.phrasesOnly);$('#done').onclick=()=>{$('#lesson').close();render()};bindFinalExamButtons();render()}
function vocab(){let available=words.filter(isVocabularyWord);$('#view').innerHTML=`<span class="eyebrow">YOUR GROWING COLLECTION</span><h1>Words become your world.</h1><p>Your vocabulary collection contains words and individual characters only. Phrases and sentences stay in lessons as practice, without mastery requirements.</p><div class="tabs"><input id="search" placeholder="Search Chinese, pinyin or English" aria-label="Search vocabulary"><button class="primary" id="review">Review focused words →</button></div><div class="word-grid" id="word-list"></div>`;const list=q=>{$('#word-list').innerHTML=available.filter(w=>(w.zh+w.py+w.en).toLowerCase().includes(q.toLowerCase())).map(w=>`<article class="word"><button data-say="${w.id}" aria-label="Hear ${esc(w.en)}">♫</button><h2>${w.zh}</h2><p>${w.py}<br>${w.en}</p><small>${requiresWriting(w)?'Word · Writing required':'Phrase · No writing requirement'}</small>${skillChecklist(w)}<small>${isWordMastered(w)?'Fully learned':'Learning · '+skillCount(w)+'/'+requiredSkills(w).length+' checks'}</small></article>`).join('')||'<p>No matching words.</p>';document.querySelectorAll('[data-say]').forEach(b=>b.onclick=()=>speak(words.find(w=>w.id===b.dataset.say).zh))};list('');$('#search').oninput=e=>list(e.target.value);$('#review').onclick=()=>start(unlocked(),true)}
function writingChars(w){return [...new Set(w.zh)].filter(c=>/[\u4e00-\u9fff]/.test(c))}
function renderWritingQuestion(w){
if(!requiresWriting(w))return false;
const s=session,index=s.index,chars=writingChars(w),character=s.writingTargets?.[index]||chars.find(c=>!state.wordWriting?.[w.id]?.includes(c))||chars[0],phase=s.isFinal?'memory':s.writingPhases?.[index]||'demo',bundle=s.writingBundles?.[index]||'legacy-'+index,mountRound=writingRound,phases=['demo','trace','copy','memory'],part=phases.indexOf(phase),labels={demo:'Guided stroke-by-stroke practice',trace:'Trace the full character',copy:'Copy with a reference',memory:'Write from memory'};
let stage='loading',attempt=0,writer=null,data=null,demoStroke=0;
const active=()=>session===s&&s.index===index&&writingRound===mountRound&&!s.answered;
$('#lesson-content').innerHTML=`<div class="modal-top"><span class="eyebrow">${s.isFinal?'FINAL WRITING CHECK':levels[s.i].title} · QUESTION ${index+1} / ${s.queue.length}</span><button class="close" aria-label="Close lesson">×</button></div><div class="bar"><div style="width:${index/s.queue.length*100}%"></div></div><div id="quest-hud">${questHUD(s)}</div>${phase==='memory'?'<div id="quiz-focus" class="quiz-focus"><span class="eyebrow">INDEPENDENT WRITING CHECK</span></div>':quizFocusMarkup(s)}${phase==='memory'?'':skillChecklist(w)}<div id="writing-word"><p>${phase==='memory'?esc(w.en):esc(w.zh)+' · '+esc(w.en)}</p><small>${phase==='memory'?'Write character '+(w.zh.indexOf(character)+1)+' from this word, from memory.':'Each writing part counts as one question. The guided stroke sequence is one question in total.'}</small></div><div class="writing-stage" id="writing-stage">${s.isFinal?'Final check':('Writing part '+(part+1)+' of 4')} · ${labels[phase]}</div><p id="writing-instructions"></p><div id="copy-reference" class="writing-copy-reference" ${phase==='copy'?'':'hidden'}><small>REFERENCE · COPY ON THE BLANK PAD BELOW</small><div class="hanzi">${phase==='copy'?character:''}</div></div><div class="canvas-wrap checked-writing-pad"><div id="checked-character" role="group" aria-label="Stroke-order guide"></div><canvas id="freehand-writing" width="640" height="640" hidden aria-label="Draw the requested stroke or character anywhere on this pad"></canvas></div><div class="writing-tools"><button class="primary" id="check-writing" hidden>${phase==='demo'?'Check my stroke':'Check my writing'}</button><button class="secondary" id="undo-writing" hidden>Undo last stroke</button><button class="secondary" id="clear" disabled>Restart this question</button><button class="secondary" id="restart-writing" disabled>${phase==='demo'?'Replay this stroke':'Retry checker'}</button></div><div id="stroke-order-steps" class="stroke-order-steps" ${phase==='demo'?'':'hidden'} aria-label="Guided stroke sequence"></div><p id="practice-result" role="status">Loading local character data…</p><div id="writing-reference" hidden></div><p class="quest-help">Shape, direction, and stroke order are checked. Your drawing can be a different size or position. Only the memory question completes writing mastery.</p><div id="answer-reaction" class="answer-reaction" hidden></div><div class="feedback" role="status"></div><div class="modal-bottom"><span class="quest-help">${s.isFinal?'Independent memory check · One question':'Guided strokes → trace → copy → memory · Four questions'}</span><button class="primary" id="next">Practice later →</button></div>`;
function fail(){if(!active())return;stage='error';$('#practice-result').textContent='Could not load the writing checker. Retry, or practice later. No writing credit has been given.';$('#restart-writing').disabled=false;$('#restart-writing').hidden=false;$('#clear').disabled=true}
function finishWritingPhase(current,valid){if(!valid())return;s.completedWritingStages=s.completedWritingStages||{};const proof=s.completedWritingStages[bundle]=s.completedWritingStages[bundle]||[];if(!s.isFinal&&phases.slice(0,part).some(p=>!proof.includes(p)))return;if(!proof.includes(current))proof.push(current);if(current==='memory'){state.wordWriting=state.wordWriting||{};const record=state.wordWriting[w.id]=state.wordWriting[w.id]||[];if(!record.includes(character))record.push(character);state.writingPractice=state.writingPractice||{};state.writingPractice[character]=(state.writingPractice[character]||0)+1}s.writingVerified=true;stage='done';answer(true);$('#writing-stage').textContent='✓ '+labels[current]+' complete';$('#practice-result').textContent=current==='memory'?'Independent shape, direction, and stroke order verified. Writing mastery updated.':'This writing question is complete. Continue to the next question.';for(const id of ['#check-writing','#undo-writing','#clear','#restart-writing'])$(id).disabled=true;$('#freehand-writing').hidden=true}
async function showGuidedStroke(valid){if(!valid())return;$('#freehand-writing').hidden=true;$('#check-writing').hidden=true;$('#undo-writing').hidden=true;$('#clear').disabled=true;$('#restart-writing').disabled=true;$('#checked-character').style.visibility='visible';await writer.hideCharacter({duration:0});await writer.hideOutline({duration:0});if(!valid())return;$('#practice-result').textContent='Watch stroke '+(demoStroke+1)+' of '+data.strokes.length+'. Then draw just that stroke.';$('#stroke-order-steps').innerHTML=data.strokes.map((_,i)=>`<span class="${i<demoStroke?'stroke-seen':i===demoStroke?'stroke-active':''}">${i+1}</span>`).join('');await writer.animateStroke(demoStroke);if(!valid())return;$('#clear').disabled=false;$('#restart-writing').disabled=false;startFreehand('demo',valid)}
function startFreehand(phase,valid){const canvas=$('#freehand-writing'),ctx=canvas.getContext('2d');let strokes=[],current=null,pointer=null,busy=false;canvas.hidden=false;$('#check-writing').hidden=false;$('#check-writing').disabled=false;$('#undo-writing').hidden=false;$('#undo-writing').disabled=false;const redraw=()=>{ctx.clearRect(0,0,640,640);ctx.strokeStyle='#3975a4';ctx.lineWidth=8;ctx.lineCap='round';ctx.lineJoin='round';for(const points of [...strokes,...(current?[current]:[])]){ctx.beginPath();ctx.moveTo(...points[0]);for(const p of points.slice(1))ctx.lineTo(...p);ctx.stroke()}};const point=e=>{const r=canvas.getBoundingClientRect();return [Math.max(0,Math.min(640,(e.clientX-r.left)*640/r.width)),Math.max(0,Math.min(640,(e.clientY-r.top)*640/r.height))]};redraw();$('#practice-result').textContent=phase==='demo'?'Your turn: draw only stroke '+(demoStroke+1)+'. Any position or size is fine.':'Draw all '+data.strokes.length+' strokes in order. Any position or size is fine.';canvas.onpointerdown=e=>{if(!valid()||busy||current||e.isPrimary===false||(e.button!==undefined&&e.button!==0))return;pointer=e.pointerId;canvas.setPointerCapture(pointer);current=[point(e)]};canvas.onpointermove=e=>{if(!current||pointer!==e.pointerId||!valid())return;current.push(point(e));redraw()};canvas.onpointerup=e=>{if(!current||pointer!==e.pointerId)return;current.push(point(e));strokes.push(current);current=null;pointer=null;redraw();$('#practice-result').textContent=phase==='demo'?'Tap Check my stroke to check this stroke before the next demonstration.':strokes.length+' / '+data.strokes.length+' strokes drawn. Check when the whole character is ready.'};canvas.onpointercancel=()=>{current=null;pointer=null;redraw()};$('#undo-writing').onclick=()=>{if(valid()&&!busy){strokes.pop();redraw();$('#practice-result').textContent='Last stroke removed. Draw it again in order.'}};$('#check-writing').onclick=async()=>{if(!valid()||busy)return;if(current){$('#practice-result').textContent='Finish your current stroke first.';return}busy=true;$('#check-writing').disabled=true;$('#clear').disabled=true;$('#restart-writing').disabled=true;$('#undo-writing').disabled=true;$('#checked-character').style.visibility='hidden';try{const result=phase==='demo'?await window.WritingCheck.checkStroke(writer,data,demoStroke,strokes):await window.WritingCheck.check(writer,data,strokes);if(!valid())return;$('#practice-result').textContent=result.message;if(result.correct){if(phase==='demo'){demoStroke++;if(demoStroke<data.strokes.length){await showGuidedStroke(valid);return}}finishWritingPhase(phase,valid);return}await writer.hideCharacter({duration:0});if(valid()){if(phase==='demo'){await writer.hideOutline({duration:0});await writer.animateStroke(demoStroke)}else if(phase==='trace')await writer.showOutline({duration:0});$('#checked-character').style.visibility=phase==='memory'||phase==='copy'?'hidden':'visible'}}catch{if(valid())$('#practice-result').textContent='Could not complete the writing check. Retry; mastery remains pending.'}finally{busy=false;if(valid()){$('#check-writing').disabled=false;$('#clear').disabled=false;$('#restart-writing').disabled=false;$('#undo-writing').disabled=false}}}}
function begin(){if(!active()||!data)return;s.completedWritingStages=s.completedWritingStages||{};const proof=s.completedWritingStages[bundle]||[];if(!s.isFinal&&phases.slice(0,part).some(p=>!proof.includes(p))){stage='blocked';$('#practice-result').textContent='An earlier writing part was skipped. Complete the four parts in order in your next quest; this question cannot award mastery.';$('#restart-writing').hidden=true;return}attempt++;const ownAttempt=attempt;stage=phase;const valid=()=>active()&&attempt===ownAttempt&&stage===phase;const target=$('#checked-character'),size=Math.max(180,Math.min(320,target.parentElement.clientWidth));if(writer){writer.cancelQuiz();if(writer.pauseAnimation)writer.pauseAnimation()}target.innerHTML='';writer=window.HanziWriter.create(target,character,{width:size,height:size,padding:18,showCharacter:false,showOutline:phase==='trace',strokeColor:'#3975a4',drawingColor:'#3975a4',outlineColor:'#d4e6f4',highlightColor:'#8dc1e6',drawingWidth:10,drawingFadeDuration:0,strokeAnimationSpeed:.8,strokeFadeDuration:0,charDataLoader:()=>data});lessonWriter=writer;$('#writing-instructions').textContent=phase==='demo'?'Watch one stroke, draw it, and check it. The next stroke appears only after yours is accepted. All strokes together count as one question.':phase==='trace'?'Trace the complete character, keeping its strokes in the demonstrated order.':phase==='copy'?'Look at the reference above and copy the whole character on the blank pad.':'Write the whole character from memory. No model is shown.';$('#checked-character').style.visibility=phase==='memory'||phase==='copy'?'hidden':'visible';$('#clear').disabled=false;$('#restart-writing').hidden=phase!=='demo';$('#restart-writing').disabled=false;if(phase==='demo')showGuidedStroke(valid).catch(fail);else startFreehand(phase,valid)}
async function load(){if(!active())return;stage='loading';try{if(!window.HanziWriter||!window.WritingCheck?.checkStroke)throw new Error('Missing checker');const response=await fetch('character-data/'+encodeURIComponent(character)+'.json');if(!response.ok)throw new Error('Missing data');data=await response.json();if(!data.strokes?.length||data.strokes.length!==data.medians?.length)throw new Error('Invalid data');if(active())begin()}catch{fail()}}
$('#clear').onclick=()=>{if(active()&&stage!=='loading'){if(phase==='demo')demoStroke=0;begin()}};$('#restart-writing').onclick=()=>{if(!active())return;if(stage==='error'){load();return}if(phase==='demo'){attempt++;const ownAttempt=attempt;showGuidedStroke(()=>active()&&attempt===ownAttempt&&stage==='demo').catch(fail)}};$('.close').onclick=()=>{stopWritingCheck();$('#lesson').close();render()};$('#next').onclick=()=>{stopWritingCheck();if(!s.answered){s.results[s.index]='skipped';s.combo=0}s.index++;question()};load();}

const scenes=[{name:'Meeting someone',lines:[['你好！','nǐ hǎo','Hello!','你好'],['你叫什么名字？','nǐ jiào shén me míng zi','What is your name?','我叫小明'],['很高兴认识你！','hěn gāo xìng rèn shi nǐ','Nice to meet you!','我也很高兴认识你']]},{name:'At a café',lines:[['你好！你想喝什么？','nǐ hǎo! nǐ xiǎng hē shén me','Hello! What would you like to drink?','我想喝茶'],['好的。你还要什么？','hǎo de. nǐ hái yào shén me','Okay. What else would you like?','请给我一杯水'],['好的，马上来。','hǎo de, mǎ shàng lái','Okay, coming right up.','谢谢']]},{name:'Making plans',lines:[['你周末喜欢做什么？','nǐ zhōu mò xǐ huan zuò shén me','What do you like doing on weekends?','我喜欢看电影'],['为什么？','wèi shén me','Why?','因为很有意思'],['我们明天见吧！','wǒ men míng tiān jiàn ba','Let’s meet tomorrow!','好的，明天见']]}];
function talk(){let scene=0,turn=0;$('#view').innerHTML=`<span class="eyebrow">A LITTLE COURAGE GOES A LONG WAY</span><h1>Let’s have a conversation.</h1><p>Guided role-play for everyday moments. Listen, then type or speak the suggested reply.</p><section class="panel"><select id="scene" aria-label="Conversation scenario">${scenes.map((s,i)=>`<option value="${i}">${s.name}</option>`).join('')}</select><div class="chat" id="chat"></div><p id="suggestion"></p><div class="input-row"><input id="reply" placeholder="Type your Chinese reply…" aria-label="Your Chinese reply"><button class="secondary" id="mic" aria-label="Speak your reply">♩ Speak</button><button class="primary" id="send">Send →</button></div><div id="conversation-reaction" class="answer-reaction" hidden aria-live="polite"></div><p id="chat-status" role="status"></p><button class="secondary" id="restart">Start again</button></section>`;function prompt(){let line=scenes[scene].lines[turn];if(!line){$('#suggestion').textContent='You completed the conversation. Try another scenario!';$('#send').disabled=true;$('#mic').disabled=true;return}let d=document.createElement('div');d.className='bubble';d.innerHTML=`${line[0]}<small>${line[1]} · ${line[2]}</small><button class="secondary">♫ Listen</button>`;d.querySelector('button').onclick=()=>speak(line[0]);$('#chat').append(d);$('#suggestion').textContent='Suggested reply: '+line[3];}function reset(){$('#conversation-reaction').hidden=true;$('#conversation-reaction').innerHTML='';turn=0;$('#chat').innerHTML='';$('#reply').value='';$('#send').disabled=false;$('#mic').disabled=false;$('#chat-status').textContent='';prompt()}$('#scene').onchange=e=>{scene=+e.target.value;reset()};$('#restart').onclick=reset;$('#send').onclick=()=>{let v=$('#reply').value.trim();if(!v)return;let expected=scenes[scene].lines[turn][3];if(normalize(v)!==normalize(expected)){showAvatarReaction(false,'#conversation-reaction');$('#chat-status').textContent='For this guided practice, try: '+expected;return}showAvatarReaction(true,'#conversation-reaction');let d=document.createElement('div');d.className='bubble me';d.textContent=v;$('#chat').append(d);$('#reply').value='';$('#chat-status').textContent='Good work. Your reply matches the practice phrase.';turn++;prompt()};$('#reply').onkeydown=e=>{if(e.key==='Enter'&&!$('#send').disabled)$('#send').click()};$('#mic').onclick=()=>{let R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R){$('#chat-status').textContent='Speech recognition is unavailable here. Type your reply, or practice aloud with the audio.';return}let r=new R();r.lang='zh-CN';r.onstart=()=>$('#chat-status').textContent='Listening…';r.onresult=e=>{$('#reply').value=e.results[0][0].transcript;$('#chat-status').textContent='Check the transcript, then send. Recognition does not assess tones.'};r.onerror=()=>$('#chat-status').textContent='Could not hear you. Check microphone permission or type your reply.';r.onend=()=>{if($('#chat-status').textContent==='Listening…')$('#chat-status').textContent='Try again or type your reply.'};r.start()};reset()}
